package io.github.jasper.monitoring.api.management.query;
import io.github.jasper.monitoring.api.management.ManagementPageRequest;
public final class ControlQuery extends ManagementQuery { public enum Sort { CREATED_AT, STATUS, ID } private final java.time.Instant from,to; private ControlQuery(ManagementPageRequest p,java.time.Instant from,java.time.Instant to){super(p);if(from==null||to==null||to.isBefore(from)||java.time.Duration.between(from,to).toDays()>31)throw new IllegalArgumentException("bounded time range required");this.from=from;this.to=to;} public static ControlQuery of(ManagementPageRequest p,java.time.Instant from,java.time.Instant to){return new ControlQuery(p,from,to);} public java.time.Instant getFrom(){return from;} public java.time.Instant getTo(){return to;} }
